A proof of the existence of a minimizer can be found in \cite[Sec 8.2]{evans2010}. Regarding the uniqueness of minimizers, assume $\boldsymbol{u}_1$ and $\boldsymbol{u}_2$ are two different minimizers of $\mathcal{F}$. In this case, $\boldsymbol{u}_1\neq\boldsymbol{u}_2$ yet $\mathcal{F}(\boldsymbol{u}_1) = \mathcal{F}(\boldsymbol{u}_2)$. Then, if $\mathcal{F}$ is strictly convex, we have that

    \begin{align}
        \mathcal{F}\left( \frac{1}{2}\boldsymbol{u}_1 + \frac{1}{2}\boldsymbol{u}_2\right) <
        \frac{1}{2}\mathcal{F}(\boldsymbol{u}_1) + \frac{1}{2}\mathcal{F}(\boldsymbol{u}_2) = \mathcal{F}(\boldsymbol{u}_1).
    \end{align}

    This is a contradiction because $\boldsymbol{u}_1$ and $\boldsymbol{u}_2$ minimize $\mathcal{F}$.

Let $j:\mathbb{R}\times\mathbb{R}_{\geq 0}\to\mathbb{R}$ be convex, in the sense that
    \begin{align}
        j(s\boldsymbol{\iota}_1+(1-s)\boldsymbol{\iota}_2) \leq s j(\boldsymbol{\iota}_1) + (1-s)j(\boldsymbol{\iota}_2)
        \quad \forall s
        \in[0,1],\, \boldsymbol{\iota}_1,\boldsymbol{\iota}_2 \in \mathbb{R}\times\mathbb{R}_{\geq 0}.
    \end{align}

    We also assume that $j = j(\alpha,\beta)$ is differentiable, increasing in $\beta$, and its gradient zero at the origin $(\alpha,\beta)=(0,0)$. For a domain $\Omega\subset\mathbb{R}^2$, consider the dissipation potential defined by \eqref{eq:dissipation_potential}.
    The constitutive law for the model is then defined by the viscous stress tensor \eqref{eq:representation_of_C}. Since $j$ depends only on the invariants of $
    \boldsymbol{\mathrm{D}}\boldsymbol{u}$, the constitutive law is rotationally-invariant, and thus frame-indifferent, as defined in appendix \ref{subapp:frame_indifference}. Next, we show that $\mathcal{J}$ is convex: let $\boldsymbol{u},\boldsymbol{v}$ be two velocity fields and $s\in[0,1]$. Then,

    \begin{align}
        \mathcal{J}(s\boldsymbol{u} + (1-s)\boldsymbol{v})=\int_\Omega j(s\alpha (\boldsymbol{u}) + (1-s)\alpha(\boldsymbol{v}),\beta(s\boldsymbol{u} + (1-s)\boldsymbol{v}))\,\mathrm{d} x.
    \end{align}

    The function $\boldsymbol{u}\mapsto\beta(\boldsymbol{u})$ is clearly convex. Moreover, since $j$ is increasing in $\beta$, it follows that

    \begin{equation}
        \begin{split}
        \int_\Omega j(s\alpha (\boldsymbol{u}) + (1-s)\alpha(\boldsymbol{v}),\beta(s\boldsymbol{u} + (1-s)\boldsymbol{v}))\,\mathrm{d} x \\ \leq  \int_\Omega j(s\alpha (\boldsymbol{u}) + (1-s)\alpha(\boldsymbol{v}),s\beta (\boldsymbol{u}) + (1-s)\beta(\boldsymbol{v}))\,\mathrm{d} x
        \end{split}
    \end{equation}

    Then, the convexity of $\mathcal{J}$ follows from the convexity of $j$. For the dissipativity of the constitutive law, first notice that $j$ is convex if and only if it has a monotonically increasing gradient:

    \begin{align}
        \left( \nabla_\iota j(\boldsymbol{\iota}_1) - \nabla_\iota j(\boldsymbol{\iota}_2) \right) \cdot (\boldsymbol{\iota}_1 - \boldsymbol{\iota}_2) \geq 0 \quad \forall \boldsymbol{\iota}_1,\boldsymbol{\iota}_2\in\mathbb{R}\times\mathbb{R}_{\geq 0}.
    \end{align}

    By setting $\boldsymbol{\iota}_1=(\alpha,\beta)$ and $\boldsymbol{\iota}_2 = \boldsymbol{0}$ above, we find that

    \begin{align}\label{eq:dissipative_visc_j}
        \frac{\partial j}{\partial\alpha}(\alpha,\beta)\alpha+ \frac{\partial j}{\partial\beta}(\alpha,\beta)\beta \geq 0 \quad \forall (\alpha,\beta)\in\mathbb{R}\times\mathbb{R}_{\geq 0},
    \end{align}

    because $\nabla_\iota j(\boldsymbol{0})=\boldsymbol{0}$ by assumption.
    This yields property \eqref{eq:dissipative_visc} by substituting the expressions in \eqref{eq:relationship_j_viscosity_2} into \eqref{eq:dissipative_visc_j}.

\label{thm:isotropy} 
    A function $\mathcal{C}:\mathbb{S}_2\to\mathbb{S}_2$ is rotationally-invariant if and only if there exist two scalar functions $\psi_1$ and $\psi_2$ from $\mathbb{R}^2$ to $\mathbb{R}$ such that

    \begin{align}\label{eq:representation_of_C_psi}
    	\mathcal{C}(\boldsymbol{\mathrm{A}}) = \psi_1(\iota_{\boldsymbol{\mathrm{A}}}) \boldsymbol{\mathrm{I}} + \psi_2(\iota_{\boldsymbol{\mathrm{A}}}) \boldsymbol{\mathrm{A}},
    \end{align}

    for all $\boldsymbol{\mathrm{A}}\in\mathbb{S}_2$, with
    $\iota_{\boldsymbol{\mathrm{A}}}:= \left( \operatorname{tr}{\boldsymbol{\mathrm{A}}}, \det{\boldsymbol{\mathrm{A}}} \right)$
    denoting the principal invariants of $\boldsymbol{\mathrm{A}}$.
